import{_ as i,o as u,c as n,a2 as o}from"./chunks/framework.CqpfiAoK.js";const w=JSON.parse('{"title":"Maelezo ya Toleo na Utunzaji wa Hati","description":"","frontmatter":{},"headers":[],"relativePath":"sw/99-文档版本与维护说明.md","filePath":"sw/99-文档版本与维护说明.md","lastUpdated":1789183869000}'),t={name:"sw/99-文档版本与维护说明.md"};function h(e,a,l,m,k,r){return u(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="maelezo-ya-toleo-na-utunzaji-wa-hati" tabindex="-1">Maelezo ya Toleo na Utunzaji wa Hati <a class="header-anchor" href="#maelezo-ya-toleo-na-utunzaji-wa-hati" aria-label="Permalink to &quot;Maelezo ya Toleo na Utunzaji wa Hati&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya hati</td><td>99</td></tr><tr><td>Moduli</td><td>Viambatanisho na Vifaa vya Rujia</td></tr><tr><td>Maneno muhimu</td><td>usimamizi wa toleo, maelezo ya utunzaji, kanuni za hati, logi ya sasisho, utunzaji wa mipangilio</td></tr></tbody></table><h2 id="_1-muhtasari-wa-mfumo-wa-hati" tabindex="-1">1. Muhtasari wa Mfumo wa Hati <a class="header-anchor" href="#_1-muhtasari-wa-mfumo-wa-hati" aria-label="Permalink to &quot;1. Muhtasari wa Mfumo wa Hati&quot;">​</a></h2><p>Mfumo wa mipangilio wa Ustaarabu wa Usawa wa Nanga unajumuisha hati 100 za Markdown, zilizohesabiwa kutoka 00 hadi 99, zimegawanywa katika moduli kumi, na kila moduli ina hati 10. Mfumo wa hati unachukua SPEC.md (Kanuni za Uundaji wa Hati) kama kizuizi cha kisheria, 00-Muhtasari wa Ulimwengu wa Hengyuanzhou kama misingi ya jumla, hati za kila moduli zinapanuliwa kwa kina kutoka vipengele tofauti, na hatimaye hati za viambatanisho 90-99 hufanya kazi ya kufahamu, kukusanya, na kupanga. Mfumo mzima wa hati unajenga hifadhi ya maarifa ya mipangilio kamili, yenye utendekanaji wa kimantiki, safu wazi, na inayojirejelea kwa kilingania.</p><p>Ubunifu wa mfumo wa hati unafuata kanuni tatu: &quot;moduli, muundo, inaweza kupanuliwa&quot;. Moduli inamaanisha kuwa kila hati inazingatia mada mahususi na ni kamili kwa yake yake; muundo unamaanisha kuwa hati zote zinafuata kanuni za muundo za umoja, kurahisisha kusoma na kutafuta; inaweza kupanuliwa inamaanisha kuwa mfumo wa hati umehifadhi nafasi ya kutosha ya upanuzi, na unaweza kuendelea kuboresha mipangilio kupitia marekebisho ya hati zilizopo na kuongeza maudhui mapya.</p><h2 id="_2-kanuni-za-uhesabu-wa-toleo" tabindex="-1">2. Kanuni za Uhesabu wa Toleo <a class="header-anchor" href="#_2-kanuni-za-uhesabu-wa-toleo" aria-label="Permalink to &quot;2. Kanuni za Uhesabu wa Toleo&quot;">​</a></h2><p>Mfumo wa hati unachukua kanuni ya uhesabu wa toleo la viwango vitatu: &quot;nambari ya toleo kuu.nambari ya toleo ya pili.nambari ya marekebisho&quot;:</p><table tabindex="0"><thead><tr><th>Kiwango cha Toleo</th><th>Kanuni ya Uhesabu</th><th>Hali ya Kichocheo</th><th>Mfano</th></tr></thead><tbody><tr><td>Nambari ya toleo kuu</td><td>Inaongezeka kuanzia 1</td><td>Mabadiliko makubwa ya muundo katika mfumo wa hati, kama vile mgawanyo upya wa moduli, mabadiliko ya mipangilio ya msingi</td><td>v1.0 → v2.0</td></tr><tr><td>Nambari ya toleo ya pili</td><td>Inaongezeka kuanzia 0</td><td>Marekebisho halisi wa maudhui ya msingi wa hati fulani, au kuongezwa kwa maudhui muhimu ya mipangilio</td><td>v1.0 → v1.1</td></tr><tr><td>Nambari ya marekebisho</td><td>Inaongezeka kuanzia 0</td><td>Marekebisho ya maandishi ya hati, marekebisho ya muundo, ujanjishaji wa masharti na mabadiliko mengi yasiyo ya halisi</td><td>v1.0 → v1.0.1</td></tr></tbody></table><p>Toleo la jumla la mfumo wa hati wa sasa ni v1.0, yaani toleo la kwanza la kuchapishwa kamili. Kila hati inarekodi nambari yake ya toleo katika kizuizi cha taarifa za hati, na nambari ya toleo la jumla la mfumo wa hati inarekodiwa kwa umoja katika hati hii.</p><h2 id="_3-mapitio-ya-kanuni-za-muundo-wa-hati" tabindex="-1">3. Mapitio ya Kanuni za Muundo wa Hati <a class="header-anchor" href="#_3-mapitio-ya-kanuni-za-muundo-wa-hati" aria-label="Permalink to &quot;3. Mapitio ya Kanuni za Muundo wa Hati&quot;">​</a></h2><p>Hati zote lazima zifuata kanuni zifuatazo za muundo wa umoja (kanuni za kina angalia SPEC.md):</p><h3 id="_3-1-kuitaja-faili" tabindex="-1">3.1 Kuitaja Faili <a class="header-anchor" href="#_3-1-kuitaja-faili" aria-label="Permalink to &quot;3.1 Kuitaja Faili&quot;">​</a></h3><p>Muundo wa jina la faili ni <code>XX-jina la hati.md</code>, ambapo XX ni nambari ya tarakimu mbili kutoka 00 hadi 99, jina ni kwa Kichina, bila nafasi.</p><h3 id="_3-2-muundo-wa-hati" tabindex="-1">3.2 Muundo wa Hati <a class="header-anchor" href="#_3-2-muundo-wa-hati" aria-label="Permalink to &quot;3.2 Muundo wa Hati&quot;">​</a></h3><p>Kila hati lazima ijumuishe vipengele vifuatavyo vya muundo:</p><ol><li><strong>Kichwa cha ngazi ya kwanza</strong>: Jina la hati (linalingana na jina la faili)</li><li><strong>Kizuizi cha taarifa za hati</strong>: Jedwali la nambari, moduli, maneno muhimu (3-5)</li><li><strong>Maudhui ya msingi</strong>: Angalau 3 sura zenye vichwa vya ngazi ya pili, kutumia vipengele vya muundo kama vile orodha, jedwali</li><li><strong>Hitimisho</strong>: Fungu la muhtasari mfupi</li><li><strong>Hati zinazohusiana</strong>: Kuorodhesha 2-3 nambari na majina ya hati zinazohusiana</li></ol><h3 id="_3-3-mahitaji-ya-idadi-ya-maneno" tabindex="-1">3.3 Mahitaji ya Idadi ya Maneno <a class="header-anchor" href="#_3-3-mahitaji-ya-idadi-ya-maneno" aria-label="Permalink to &quot;3.3 Mahitaji ya Idadi ya Maneno&quot;">​</a></h3><p>Maudhui ya msingi ya kila hati yapaswa kuwa ya herufi 800 au zaidi (bila kichwa na taarifa za meta).</p><h3 id="_3-4-mtindo-wa-kuandika" tabindex="-1">3.4 Mtindo wa Kuandika <a class="header-anchor" href="#_3-4-mtindo-wa-kuandika" aria-label="Permalink to &quot;3.4 Mtindo wa Kuandika&quot;">​</a></h3><ul><li>Mtindo wa hati ya mipangilio wenye uzito na mtaratibu, unaofanana na ensaiklopedia/kusanyikwa kwa mipangilio</li><li>Kutumia masharti ya umoja kama vile &quot;Hengyuanzhou&quot;, &quot;nanga&quot;, &quot;usawa&quot;</li><li>Mipangilio mpya iliyotolewa lazima iwe na utendekanaji wa kimantiki na mipangilio iliyopo, ikilingana na kanuni ya &quot;kulingana na ukweli, kuboresha sheria&quot;</li></ul><h2 id="_4-shirika-la-utunzaji-na-wajibu" tabindex="-1">4. Shirika la Utunzaji na Wajibu <a class="header-anchor" href="#_4-shirika-la-utunzaji-na-wajibu" aria-label="Permalink to &quot;4. Shirika la Utunzaji na Wajibu&quot;">​</a></h2><h3 id="_4-1-kamati-ya-utunzaji-wa-mipangilio" tabindex="-1">4.1 Kamati ya Utunzaji wa Mipangilio <a class="header-anchor" href="#_4-1-kamati-ya-utunzaji-wa-mipangilio" aria-label="Permalink to &quot;4.1 Kamati ya Utunzaji wa Mipangilio&quot;">​</a></h3><p>Kamati ya Utunzaji wa Mipangilio ni shirika la juu la utunzaji wa mfumo wa hati, inajumuisha wabunifu wa mipangilio wenye uzoefu, wataalam wa ukaguzi wa kimantiki, na wawakilishi wa watumiaji. Wajibu wake wa msingi unajumuisha:</p><ul><li>Kuthibitisha muundo wa jumla wa mfumo wa hati na mipango ya marekebisho makubwa</li><li>Kukagua mabadiliko makubwa ya mipangilio, kuhakikisha utendekanaji na mipangilio ya msingi</li><li>Kukata sheria ya mizozo ya mipangilio, kutoa maelezo ya mamlaka</li><li>Kukusanya mara kwa mara kujikagua kwa utendekanaji kamili wa mipangilio</li><li>Kuchapisha sasisho ya toleo la jumla la mfumo wa hati</li></ul><h3 id="_4-2-mlinzi-wa-moduli" tabindex="-1">4.2 Mlinzi wa Moduli <a class="header-anchor" href="#_4-2-mlinzi-wa-moduli" aria-label="Permalink to &quot;4.2 Mlinzi wa Moduli&quot;">​</a></h3><p>Kila moduli inateuliwa mlinzi wa moduli mmoja, anayehusika na utunzaji wa kila siku wa hati 10 za moduli hiyo. Wajibu wake unajumuisha:</p><ul><li>Kufuatilia utendekanaji wa mipangilio wa hati ndani ya moduli</li><li>Kukagua ombi la marekebisho la hati ndani ya moduli</li><li>Kulenga uhusiano wa kati ya hati ndani ya moduli</li><li>Kukusanya maoni na mapendekezo ya watumiaji kuhusu maudhui ya moduli</li><li>Kutoripoti mara kwa mara hali ya utunzaji wa moduli kwa Kamati ya Utunzaji wa Mipangilio</li></ul><h3 id="_4-3-mbungi-wa-hati" tabindex="-1">4.3 Mbungi wa Hati <a class="header-anchor" href="#_4-3-mbungi-wa-hati" aria-label="Permalink to &quot;4.3 Mbungi wa Hati&quot;">​</a></h3><p>Kila mbungi anayefuata masharti anaweza kushiriki katika uundaji na marekebisho ya hati. Wajibu wa mbungi unajumuisha:</p><ul><li>Kuunda au kurekebisha hati kulingana na kanuni za muundo</li><li>Kuhakikisha kuwa maudhui ya uundaji yanapita katika ukaguzi wa jedwali la kujikagua utofauti wa mipangilio . Kuambatisha maelezo ya marekebisho ya kina wakati wa kutuma marekebisho</li><li>Kushirikiana na kazi ya ukaguzi ya walinzi na kamati</li></ul><h2 id="_5-mchakato-wa-marekebisho" tabindex="-1">5. Mchakato wa Marekebisho <a class="header-anchor" href="#_5-mchakato-wa-marekebisho" aria-label="Permalink to &quot;5. Mchakato wa Marekebisho&quot;">​</a></h2><h3 id="_5-1-mchakato-wa-marekebisho-wa-kawaida" tabindex="-1">5.1 Mchakato wa Marekebisho wa Kawaida <a class="header-anchor" href="#_5-1-mchakato-wa-marekebisho-wa-kawaida" aria-label="Permalink to &quot;5.1 Mchakato wa Marekebisho wa Kawaida&quot;">​</a></h3><ol><li><strong>Kutuma ombi</strong>: Mbungi anatuma ombi la marekebisho kwa mlinzi wa moduli, ikiwa ni pamoja na nambari ya hati iliyorekebishwa, maelezo ya maudhui ya marekebisho, na sababu ya marekebisho.</li><li><strong>Ukaguzi wa moduli</strong>: Mlinzi wa moduli anagagua maudhui ya marekebisho, akizingatia hasa ukaguzi wa kanuni za muundo na utendekanaji ndani ya moduli. Baada ya kupita katika ukaguzi, anatuma kwa Kamati ya Utunzaji wa Mipangilio.</li><li><strong>Uthibitisho wa kamati</strong>: Kamati ya Utunzaji wa Mipangilio hufanya uthibitisho wa mwisho wa maudhui ya marekebisho, akizingatia hasa ukaguzi wa utendekanaji kati ya moduli na utendekanaji wa mipangilio ya msingi.</li><li><strong>Kutekeleza marekebisho</strong>: Baada ya kupita katika uthibitisho, mlinzi wa moduli au mbungi wa asili anatekeleza marekebisho ya hati.</li><li><strong>Sasisha toleo</strong>: Baada ya marekebisho kukamilika, sasisha nambari ya toleo la hati, na irekodi katika logi ya sasisho ya hati hii.</li><li><strong>Usawazishaji unaohusiana</strong>: Ikiwa maudhui ya marekebisho yanaathiri hati nyingine, lazima hati zinazohusiana zirekebishwe kwa usawazishaji.</li></ol><h3 id="_5-2-mchakato-wa-marekebisho-ya-dharura" tabindex="-1">5.2 Mchakato wa Marekebisho ya Dharura <a class="header-anchor" href="#_5-2-mchakato-wa-marekebisho-ya-dharura" aria-label="Permalink to &quot;5.2 Mchakato wa Marekebisho ya Dharura&quot;">​</a></h3><p>Kwa hali ya dharura ambapo utofauti makubwa wa mipangilio au makosa yanawekwa wazi, mchakato wa marekebisho wa dharura unaweza kuanzishwa:</p><ol><li><strong>Ripoti ya dharura</strong>: Mgundua anaripoti mara moja tatizo hilo kwa Kamati ya Utunzaji wa Mipangilio.</li><li><strong>Uthibitisho wa haraka</strong>: Kamati inakamilisha uthibitisho wa dharura ndani ya masaa 24, na kutoa mpango wa marekebisho.</li><li><strong>Kutekeleza marekebisho</strong>: Mtu mahususi anateuliwa kutekeleza marekebisho mara moja.</li><li><strong>Kurekodi baadaye</strong>: Baada ya marekebisho kukamilika, ombi la marekebisho na rekodi ya ukaguzi zimerekodiwa baadaye.</li></ol><h3 id="_5-3-marekebisho-kamili-za-mara-kwa-mara" tabindex="-1">5.3 Marekebisho Kamili za Mara kwa Mara <a class="header-anchor" href="#_5-3-marekebisho-kamili-za-mara-kwa-mara" aria-label="Permalink to &quot;5.3 Marekebisho Kamili za Mara kwa Mara&quot;">​</a></h3><p>Kamati ya Utunzaji wa Mipangilio inakusanya mara moja kwa kila mwaka marekebisho kamili za mfumo wa hati, ikiwa ni pamoja na:</p><ul><li>Kujikagua kwa utendekanaji kamili wa mipangilio</li><li>Usindikaji wa kati ya maoni ya watumiaji</li><li>Ujanjishaji na sasisho la mfumo wa masharti</li><li>Sasisho la usawazishaji wa hati za fahirisi</li><li>Ukaguzi na marekebisho ya umoja wa muundo wa hati</li></ul><h2 id="_6-logi-ya-sasisho" tabindex="-1">6. Logi ya Sasisho <a class="header-anchor" href="#_6-logi-ya-sasisho" aria-label="Permalink to &quot;6. Logi ya Sasisho&quot;">​</a></h2><h3 id="v1-0-kuchapishwa-kwa-kwanza-kwa-ukamilifu" tabindex="-1">v1.0 (Kuchapishwa kwa Kwanza kwa Ukamilifu) <a class="header-anchor" href="#v1-0-kuchapishwa-kwa-kwanza-kwa-ukamilifu" aria-label="Permalink to &quot;v1.0 (Kuchapishwa kwa Kwanza kwa Ukamilifu)&quot;">​</a></h3><ul><li>Kukamilisha uundaji na kuchapishwa kwa hati zote 100 . Kuanzisha muundo kamili na kanuni za muundo za mfumo wa hati</li><li>Kukamilisha ufunuo wa maudhui wa moduli kumi</li><li>Kuanzisha mfumo wa fahirisi ya viambatanisho (kamusi ya masharti, fahirisi ya mifumo, fahirisi ya kisheria, kronikali, orodha ya makabila yote, watu na mashirika, FAQ, jedwali la kujikagua, mapendekezo ya upanuzi, maelezo ya toleo)</li></ul><h3 id="eneo-la-rekodi-ya-sasisho-la-toleo-la-baadaye" tabindex="-1">Eneo la Rekodi ya Sasisho la Toleo la Baadaye <a class="header-anchor" href="#eneo-la-rekodi-ya-sasisho-la-toleo-la-baadaye" aria-label="Permalink to &quot;Eneo la Rekodi ya Sasisho la Toleo la Baadaye&quot;">​</a></h3><p>(Maudhui ya sasisho la toleo la baadaye yataongezwa rekodi hapa, ikiwa ni pamoja na nambari ya toleo, tarehe ya kuchapishwa, muhtasari wa maudhui muhimu ya sasisho)</p><h2 id="_7-kanuni-za-rujia-na-rujia-ya-kati-ya-hati" tabindex="-1">7. Kanuni za Rujia na Rujia ya Kati ya Hati <a class="header-anchor" href="#_7-kanuni-za-rujia-na-rujia-ya-kati-ya-hati" aria-label="Permalink to &quot;7. Kanuni za Rujia na Rujia ya Kati ya Hati&quot;">​</a></h2><h3 id="_7-1-rujia-ya-ndani" tabindex="-1">7.1 Rujia ya Ndani <a class="header-anchor" href="#_7-1-rujia-ya-ndani" aria-label="Permalink to &quot;7.1 Rujia ya Ndani&quot;">​</a></h3><p>Rujia ya kati ya hati hutumia muundo wa &quot;nambari ya hati-jina la hati&quot;, kwa mfano &quot;angalia Hati 84 &#39;Mpango wa Jumla wa Itifaki ya Kale&#39;&quot;. Wakati wa kurujia, lazima uhakikishe kuwa hati inayorujiliwa kweli ipo na nambari na jina ni sahihi.</p><h3 id="_7-2-rujia-ya-masharti" tabindex="-1">7.2 Rujia ya Masharti <a class="header-anchor" href="#_7-2-rujia-ya-masharti" aria-label="Permalink to &quot;7.2 Rujia ya Masharti&quot;">​</a></h3><p>Wakati wa kutumia masharti fulani ya msingi kwa mara ya kwanza, inaweza kuonyeshwa kwamba inapaswa kurejelea kipengele kinacholingana katika Hati 90 &quot;Kamusi ya Masharti&quot;. Hakuna haja ya kurudia kuonyesha wakati wa kutumia masharti sawa baadaye.</p><h3 id="_7-3-rujia-ya-nje" tabindex="-1">7.3 Rujia ya Nje <a class="header-anchor" href="#_7-3-rujia-ya-nje" aria-label="Permalink to &quot;7.3 Rujia ya Nje&quot;">​</a></h3><p>Ikiwa inahitajika kurujia nyenzo halisi au kazi za ubuni nje ya mfumo wa mipangilio, lazima uonyeshe chanzo, na kuelezea wazi kwamba rujia hii ni nyenzo ya rujia chini ya kanuni ya &quot;kulingana na ukweli&quot;, haiwakilishi mfumo wa mipangilio unakabidhi kabisa maudhui yake.</p><h2 id="_8-mchakato-wa-uhakikisho-wa-ubora" tabindex="-1">8. Mchakato wa Uhakikisho wa Ubora <a class="header-anchor" href="#_8-mchakato-wa-uhakikisho-wa-ubora" aria-label="Permalink to &quot;8. Mchakato wa Uhakikisho wa Ubora&quot;">​</a></h2><h3 id="_8-1-kujikagua-utofauti-wa-mipangilio" tabindex="-1">8.1 Kujikagua Utofauti wa Mipangilio <a class="header-anchor" href="#_8-1-kujikagua-utofauti-wa-mipangilio" aria-label="Permalink to &quot;8.1 Kujikagua Utofauti wa Mipangilio&quot;">​</a></h3><p>Hati zote mpya zilizoundwa na zilizorekebishwa lazima zipite katika vipengele vyote vya ukaguzi vya Hati 97 &quot;Jedwali la Kujikagua Utofauti wa Mipangilio&quot;, ikiwa ni pamoja na zaidi ya 40 ukaguzi katika kategori tatu: utendekanaji wa mipangilio ya msingi, utendekanaji wa kimantiki kati ya moduli, na kanuni za muundo wa hati.</p><h3 id="_8-2-ukaguzi-wa-kati-ya-mbinguni" tabindex="-1">8.2 Ukaguzi wa Kati ya Mbinguni <a class="header-anchor" href="#_8-2-ukaguzi-wa-kati-ya-mbinguni" aria-label="Permalink to &quot;8.2 Ukaguzi wa Kati ya Mbinguni&quot;">​</a></h3><p>Kila hati lazima ipite katika ukaguzi wa kati ya mbinguni wa angalau mzungu mmoja mwingine kabla ya kuchapishwa rasmi, akizingatia hasa ukaguzi wa utendekanaji wa kimantiki kati ya moduli na ujanjishaji wa masharti.</p><h3 id="_8-3-mchakato-wa-maoni-ya-mtumiaji" tabindex="-1">8.3 Mchakato wa Maoni ya Mtumiaji <a class="header-anchor" href="#_8-3-mchakato-wa-maoni-ya-mtumiaji" aria-label="Permalink to &quot;8.3 Mchakato wa Maoni ya Mtumiaji&quot;">​</a></h3><p>Mfumo wa hati unaanzisha chanzo cha maoni ya mtumiaji, ambapo watumiaji wanaweza kutuma maoni kwa njia zifuatazo:</p><ul><li>Kuripoti utofauti wa mipangilio na makosa ya kimantiki . Kuweka mawazo ya ukosefu wa ujanjishaji wa masharti</li><li>Kupendekeza kuongeza au kurekebisha maudhui mahususi</li><li>Kuonyesha makosa ya muundo na maandishi</li></ul><p>Maoni yote yanashughulikiwa kwa uainishaji na mlinzi wa moduli, na maoni muhimu yanatumiwa kwa Kamati ya Utunzaji wa Mipangilio kwa ajili ya kujadili.</p><h3 id="_8-4-ripoti-ya-utendekanaji-ya-robo" tabindex="-1">8.4 Ripoti ya Utendekanaji ya Robo <a class="header-anchor" href="#_8-4-ripoti-ya-utendekanaji-ya-robo" aria-label="Permalink to &quot;8.4 Ripoti ya Utendekanaji ya Robo&quot;">​</a></h3><p>Kamati ya Utunzaji wa Mipangilio inachapisha &quot;Ripoti ya Utendekanaji wa Mipangilio&quot; kila robo, maudhui yake ni pamoja na:</p><ul><li>Utofauti wa mipangilio uliogunduliwa katika robo hii na hali ya usindikaji</li><li>Takwimu za marekebisho ya hati katika robo hii</li><li>Maendeleo ya ujanjishaji wa masharti</li><li>Hali ya usindikaji wa maoni ya watumiaji</li><li>Mpango wa utunzaji wa robo inayofuata</li></ul><h2 id="_9-uhifadhi-na-usambazaji-wa-hati" tabindex="-1">9. Uhifadhi na Usambazaji wa Hati <a class="header-anchor" href="#_9-uhifadhi-na-usambazaji-wa-hati" aria-label="Permalink to &quot;9. Uhifadhi na Usambazaji wa Hati&quot;">​</a></h2><h3 id="_9-1-muundo-wa-uhifadhi" tabindex="-1">9.1 Muundo wa Uhifadhi <a class="header-anchor" href="#_9-1-muundo-wa-uhifadhi" aria-label="Permalink to &quot;9.1 Muundo wa Uhifadhi&quot;">​</a></h3><p>Hati zote zimehifadhiwa katika muundo wa Markdown (.md), kuhakikisha uwezo wa kusoma kwa kila jukwaa na urahisi wa usimamizi wa toleo. Hati hutumia usimbaji wa UTF-8, kusaidia Kichina na herufi maalum.</p><h3 id="_9-2-muundo-wa-saraka" tabindex="-1">9.2 Muundo wa Saraka <a class="header-anchor" href="#_9-2-muundo-wa-saraka" aria-label="Permalink to &quot;9.2 Muundo wa Saraka&quot;">​</a></h3><p>Hati zimehifadhiwa kwa umoja katika saraka ya <code>anchor-docs/</code>, jina la faili ni katika muundo wa <code>XX-jina la hati.md</code>. SPEC.md, kama faili la kanuni, pia limehifadhiwa katika saraka hiyo hiyo.</p><h3 id="_9-3-usimamizi-wa-toleo" tabindex="-1">9.3 Usimamizi wa Toleo <a class="header-anchor" href="#_9-3-usimamizi-wa-toleo" aria-label="Permalink to &quot;9.3 Usimamizi wa Toleo&quot;">​</a></h3><p>Inapendekezwa kutumia mifumo ya kudhibiti toleo kama vile Git kwa ajili ya usimamizi wa toleo la hati, kila wakati wa kutuma marekebisho kushikamana na ujumbe wa commit wa kina, kurekodi maudhui na sababu ya marekebisho.</p><h3 id="_9-4-njia-za-usambazaji" tabindex="-1">9.4 Njia za Usambazaji <a class="header-anchor" href="#_9-4-njia-za-usambazaji" aria-label="Permalink to &quot;9.4 Njia za Usambazaji&quot;">​</a></h3><p>Mfumo wa hati unaweza kusambazwa kwa njia zifuatazo:</p><ul><li>Kupakiwa kama faili la kilichosanywa ZIP kwa kupakua . Kuwekwa kama tovuti tulivu ili kuangalia mtandaoni</li><li>Kubadilishwa kuwa muundo wa PDF au EPUB kwa ajili ya kusoma</li><li>Kuingizwa katika mfumo wa usimamizi wa maarifa kwa ajili ya usimamizi wa muundo</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Maelezo ya Toleo na Utunzaji wa Hati ni &quot;katiba ya usimamizi&quot; ya mfumo wa mipangilio wa Ustaarabu wa Usawa wa Nanga. Inaanzisha kanuni za toleo, shirika la utunzaji, mchakato wa marekebisho, mchakato wa uhakikisho wa ubora, na njia za uhifadhi na usambazaji wa mfumo wa hati, kuhakikisha kuwa mfumo huu mkubwa wa mipangilio uliojumuisha hati 100 unaweza kudumisha utaratibu na utendekanaji kila wakati katika mchakato wa ukuaji wa kushindania. Mfumo mzuri wa mipangilio hauhitaji tu maudhui mazuri, lakini pia unahitaji mchakato kamili wa utunzaji ili kuhakikisha ukuaji wake mzuri wa muda mrefu. Hati hii ndiyo mbeba msingi wa mchakato huu.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>97-Jedwali la Kujikagua Utofauti wa Mipangilio</li><li>90-Kamusi ya Masharti</li><li>00-Muhtasari wa Ulimwengu wa Hengyuanzhou</li></ul>',77)])])}const d=i(t,[["render",h]]);export{w as __pageData,d as default};
